-- =====================================================================
--  Módulo Obras (POA 2024/2025/2026) — registro + tabla + carga.
--  Reporte geográfico de obra pública municipal. Coordenadas extraídas
--  resolviendo los links cortos de Google Maps (maps.app.goo.gl) del
--  archivo fuente. delegacion_geo se precalculó por point-in-polygon
--  contra los límites oficiales (delegaciones_geo). Idempotente.
-- =====================================================================
SET NAMES utf8mb4;
USE portal_qro;

VALUES ('obras', 'Obras',
        'Obra pública municipal (POA 2024-2026) · mapa, inversión y avance',
        'hammer', 'modules/obras/index.php', '#c85a2b', 8)
ON DUPLICATE KEY UPDATE
  nombre=VALUES(nombre), descripcion=VALUES(descripcion), icono=VALUES(icono),
  ruta=VALUES(ruta), color=VALUES(color), orden=VALUES(orden);

CREATE TABLE IF NOT EXISTS obras (
  id             INT UNSIGNED NOT NULL AUTO_INCREMENT,
  num            SMALLINT UNSIGNED NULL,
  clave          VARCHAR(20) NOT NULL,
  anio           SMALLINT UNSIGNED NOT NULL,
  nombre         VARCHAR(500) NOT NULL,
  rubro          VARCHAR(160) NULL,
  delegacion     VARCHAR(120) NULL COMMENT 'del listado (puede ser VARIAS)',
  colonia        VARCHAR(200) NULL,
  fecha_inicio   DATE NULL,
  fecha_termino  DATE NULL,
  ejercido       DECIMAL(15,2) NULL COMMENT 'inversion ejercida MXN',
  avance         DECIMAL(5,4) NULL COMMENT '0..1',
  estatus        VARCHAR(40) NULL,
  ben_dir        INT UNSIGNED NULL,
  ben_ind        INT UNSIGNED NULL,
  maps_url       VARCHAR(255) NULL,
  lat            DECIMAL(10,7) NULL,
  lng            DECIMAL(10,7) NULL,
  delegacion_geo VARCHAR(120) NULL COMMENT 'delegacion oficial por geometria',
  ficha          VARCHAR(255) NULL COMMENT 'ruta local del PDF (referencia)',
  activo         TINYINT(1) NOT NULL DEFAULT 1,
  creado_en      TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_anio (anio), KEY idx_estatus (estatus), KEY idx_rubro (rubro),
  KEY idx_deleg (delegacion_geo), KEY idx_coord (lat,lng)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DELETE FROM obras;
ALTER TABLE obras AUTO_INCREMENT = 1;

